{{-- Tambahan interaksi Dashboard Utama: tombol, kartu, sidebar, pencarian. Tidak mengubah kode dashboard. --}}
<style>
.btn,.kpi{position:relative;overflow:hidden;cursor:pointer}.kpi{transition:transform .3s,box-shadow .3s}.kpi:hover{transform:translateY(-4px);box-shadow:0 14px 34px rgba(11,31,58,.1)}
.sx-rp{position:absolute;border-radius:50%;background:rgba(15,122,79,.25);transform:scale(0);animation:sxrp .6s ease-out forwards;pointer-events:none}@keyframes sxrp{to{transform:scale(4);opacity:0}}
.sx-ov{position:fixed;inset:0;z-index:80;background:rgba(11,31,58,.45);backdrop-filter:blur(5px);opacity:0;pointer-events:none;transition:opacity .3s;display:grid;place-items:center;padding:16px}.sx-ov.on{opacity:1;pointer-events:auto}
.sx-box{background:#fff;border-radius:18px;width:min(560px,100%);max-height:90vh;overflow:auto;padding:22px;box-shadow:0 30px 80px rgba(11,31,58,.35);transform:translateY(30px) scale(.95);transition:transform .45s cubic-bezier(.2,.8,.2,1)}.sx-ov.on .sx-box{transform:none}
.sx-ov.dr{place-items:stretch end;padding:0}.dr .sx-box{width:min(480px,100%);max-height:none;height:100%;border-radius:18px 0 0 18px;transform:translateX(100%)}.dr.on .sx-box{transform:none}
.sx-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.sx-h h3{font-size:18px;margin:0}.sx-x{border:0;background:#eef3fa;width:32px;height:32px;border-radius:50%;cursor:pointer;font-size:16px;transition:.25s}.sx-x:hover{background:#fee2e2;transform:rotate(90deg)}
.sx-f{display:grid;grid-template-columns:1fr 1fr;gap:12px}.sx-f label{display:block;font-weight:600;font-size:12px;color:#334155}.sx-f .w{grid-column:1/-1}
.sx-f input,.sx-f select,.sx-s{width:100%;margin-top:6px;padding:11px 12px;border:1.5px solid transparent;border-radius:10px;background:#eef3fa;font:inherit;outline:0;transition:.25s}.sx-f input:focus,.sx-f select:focus,.sx-s:focus{border-color:#0f7a4f;background:#fff;box-shadow:0 0 0 4px rgba(15,122,79,.12)}
.sx-er{border-color:#dc2626!important;animation:sxsk .4s}@keyframes sxsk{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}.sx-em{color:#dc2626;font-size:11px;font-weight:500;margin-top:4px;min-height:0}
.sx-a{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.sx-b{border:0;padding:11px 16px;border-radius:10px;font:600 13px Inter,sans-serif;cursor:pointer;background:#eef3fa;color:#0f1b2d;transition:.25s}.sx-b:hover{transform:translateY(-2px)}.sx-b.g{background:#0f7a4f;color:#fff}.sx-b:disabled{opacity:.5;cursor:wait}
.sx-dz{border:2px dashed #b8c6da;border-radius:14px;padding:24px;text-align:center;color:#64748b;cursor:pointer;transition:.25s;margin:12px 0}.sx-dz:hover,.sx-dz.ov{border-color:#0f7a4f;background:#f0fbf5;transform:scale(1.01)}
.sx-li{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:11px 12px;border:1px solid #e5e9f0;border-radius:12px;margin-bottom:8px;animation:sxin .5s cubic-bezier(.2,.8,.2,1) backwards;animation-delay:calc(var(--i,0)*50ms);transition:.25s}.sx-li.c{cursor:pointer}.sx-li.c:hover{background:#f6f9fe;transform:translateX(4px)}.sx-li small{display:block;color:#64748b}
@keyframes sxin{from{opacity:0;transform:translateX(24px)}}.sx-pb{height:6px;border-radius:6px;background:#e2e8f0;overflow:hidden;margin-top:6px}.sx-pb i{display:block;height:100%;width:0;background:linear-gradient(90deg,#0f7a4f,#34d399);transition:width .5s}
.sx-mn{position:absolute;right:0;top:calc(100% + 8px);width:250px;background:#fff;border:1px solid #e5e9f0;border-radius:14px;box-shadow:0 20px 50px rgba(11,31,58,.2);padding:8px;z-index:50;opacity:0;transform:translateY(-8px) scale(.97);pointer-events:none;transition:.25s}.sx-mn.on{opacity:1;transform:none;pointer-events:auto}
.sx-mn a,.sx-mn button{display:flex;gap:9px;align-items:center;width:100%;padding:10px;border:0;background:none;border-radius:9px;color:#0f1b2d;text-decoration:none;font:500 13px Inter,sans-serif;cursor:pointer;text-align:left}.sx-mn a:hover,.sx-mn button:hover{background:#eef3fa}
.sx-sr{position:absolute;left:0;right:0;top:calc(100% + 6px);background:#fff;border:1px solid #e5e9f0;border-radius:12px;box-shadow:0 20px 50px rgba(11,31,58,.2);z-index:50;max-height:300px;overflow:auto;display:none}.sx-sr button{display:block;width:100%;text-align:left;padding:10px 12px;border:0;background:none;font:500 13px Inter,sans-serif;cursor:pointer}.sx-sr button:hover{background:#eef3fa}.sx-sr small{color:#64748b}
.sx-t{position:fixed;right:24px;bottom:24px;background:#0b1f3a;color:#fff;padding:12px 18px;border-radius:12px;font-weight:600;transform:translateY(90px);opacity:0;transition:.4s cubic-bezier(.2,.8,.2,1);z-index:99;max-width:340px}.sx-t.on{transform:none;opacity:1}
@media(max-width:560px){.sx-f{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
<div class="sx-ov" id="sxOv"><div class="sx-box" role="dialog" aria-modal="true"></div></div><div class="sx-t" id="sxT"></div>
<script>
(function(){
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const R={pendaftaran:"{{ route('pendaftaran') }}",verifikasi:"{{ route('verifikasi') }}",seleksi:"{{ route('seleksi') }}",calon:"{{ route('calon') }}"};
const LS=k=>{try{return JSON.parse(localStorage.getItem(k))||[]}catch(e){return[]}},SV=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
let SIS=LS('siadds_siswa'),DOK=LS('siadds_dok'),KON=LS('siadds_konversi');
const K=$$('.kpi strong'),fmt=n=>(+n).toLocaleString('id-ID');
const G=$$('.gender b[data-count]');
const add=(i,n)=>{if(K[i])K[i].dataset.count=(+K[i].dataset.count)+n};
SIS.forEach(s=>{add(0,1);add(1,1);const g=G[s.jk=='L'?0:1];if(g)g.dataset.count=+g.dataset.count+1});add(3,DOK.length);KON.forEach(()=>{add(1,1);add(2,-1)});
function bump(i,n){const e=K[i];if(!e)return;const a=+e.dataset.count,b=a+n;e.dataset.count=b;const t0=performance.now();(function f(t){const p=Math.min(1,(t-t0)/700);e.textContent=fmt(Math.round(a+(b-a)*p));if(p<1)requestAnimationFrame(f)})(t0)}
const ov=$('#sxOv'),box=$('.sx-box',ov);
function open(title,html,drawer){ov.classList.toggle('dr',!!drawer);box.innerHTML=`<div class="sx-h"><h3>${title}</h3><button class="sx-x" aria-label="Tutup">✕</button></div>${html}`;ov.classList.add('on');$('.sx-x',box).onclick=close;box.scrollTop=0;const f=$('input,select',box);f&&setTimeout(()=>f.focus(),300)}
function close(){ov.classList.remove('on')}ov.addEventListener('click',e=>{if(e.target==ov)close()});document.addEventListener('keydown',e=>{if(e.key=='Escape'){close();mn.classList.remove('on')}});
const toast=m=>{const t=$('#sxT');t.textContent=m;t.classList.add('on');clearTimeout(t._);t._=setTimeout(()=>t.classList.remove('on'),2800)};
const AKT=[['Anisa Rahmawati','X-B','8078121101','P'],['Dimas Pratama','X-A','8078121102','L'],['Muhammad Rizki','X-C','8078121103','L'],['Bagas Saputra','XI-IPS 1','8059124409','L'],['Muhammad Farhan','X-A','8064512903','L'],['Zaskia Nur Azizah','XI-IPA','8078921438','P']];
const ALM=[['Siti Khoirun Nisa','Lulus 2023','7956121001','P'],['Ahmad Zulkifli','Lulus 2023','7956121002','L'],['Rahmat Hidayat','Lulus 2022','7856121003','L']];
const CLN=[['Rian Ardiansyah','PPDB-2024-055','8087712391'],['Nurul Hidayati','PPDB-2024-052','8081293341'],['Zaskia Nur Azizah','PPDB-2024-041','8078921438']];
const row=(h,i,c)=>`<div class="sx-li ${c?'c':''}" style="--i:${i}" ${c||''}>${h}</div>`;
/* ===== Tambah Siswa ===== */
function formSiswa(){open('Tambah Siswa Baru',`<div class="sx-f"><label class="w">Nama Lengkap *<input id="fN" maxlength="80"><div class="sx-em"></div></label><label>NISN (10 digit) *<input id="fS" inputmode="numeric" maxlength="10"><div class="sx-em"></div></label><label>Jenis Kelamin<select id="fG"><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label><label>Kelas<select id="fK"><option>X-A</option><option>X-B</option><option>X-C</option><option>XI-IPA</option><option>XI-IPS 1</option><option>XI-IPS 2</option><option>XII-MIA</option><option>XII-IIS 1</option><option>XII-IIS 2</option></select></label><label>Asal Sekolah<input id="fA" maxlength="60"></label></div><div class="sx-a"><button class="sx-b" id="fC">Batal</button><button class="sx-b g" id="fO">Simpan Siswa</button></div>`);
$('#fC').onclick=close;$('#fO').onclick=()=>{const n=$('#fN'),s=$('#fS');let ok=1;const bad=(el,m)=>{ok=0;el.classList.remove('sx-er');el.offsetWidth;el.classList.add('sx-er');el.nextElementSibling.textContent=m};
 [n,s].forEach(e=>{e.classList.remove('sx-er');e.nextElementSibling.textContent=''});
 if(n.value.trim().length<3)bad(n,'Nama wajib diisi (min. 3 huruf)');
 if(!/^\d{10}$/.test(s.value))bad(s,'NISN harus 10 digit angka');else if(SIS.some(x=>x.nisn==s.value)||AKT.some(x=>x[2]==s.value))bad(s,'NISN sudah terdaftar');
 if(!ok)return;const d={nama:n.value.trim(),nisn:s.value,jk:$('#fG').value,kelas:$('#fK').value,asal:$('#fA').value.trim()};SIS.push(d);SV('siadds_siswa',SIS);
 bump(0,1);bump(1,1);const g=G[d.jk=='L'?0:1];g&&(g.dataset.count=+g.dataset.count+1,g.textContent=fmt(g.dataset.count));
 logAdd(`Admin menambahkan siswa baru ${esc(d.nama)} (Kelas ${d.kelas}).`);close();toast(d.nama+' berhasil ditambahkan')}}
function logAdd(t){const l=$('.log');if(!l)return;const d=document.createElement('div');d.className='log';d.style.animation='sxin .6s both';d.innerHTML=t+'<small>Baru saja</small>';l.parentNode.insertBefore(d,l)}
/* ===== Upload Dokumen ===== */
function formUpload(){let F=[];const J=['Kartu Keluarga (KK)','Akta Kelahiran','Pas Foto 3x4','Ijazah / SKL','KIP / PKH'];
open('Upload Dokumen',`<div class="sx-f"><label>Jenis Dokumen<select id="uJ">${J.map(j=>'<option>'+j+'</option>').join('')}</select></label><label>Nama Siswa<input id="uS" list="uL" placeholder="Ketik nama siswa"><datalist id="uL">${[...AKT.map(a=>a[0]),...SIS.map(s=>s.nama)].map(n=>'<option value="'+esc(n)+'">').join('')}</datalist></label></div>
<div class="sx-dz" id="uD"><b>Seret berkas ke sini</b> atau klik untuk memilih<br><small>PDF / JPG / PNG • maks. 5 MB per berkas</small><input type="file" id="uF" multiple accept=".pdf,.jpg,.jpeg,.png" hidden></div><div id="uLs"></div><div class="sx-a"><button class="sx-b" id="uC">Batal</button><button class="sx-b g" id="uO" disabled>Unggah</button></div>`);
const dz=$('#uD'),inp=$('#uF'),ls=$('#uLs');const draw=()=>{ls.innerHTML=F.map((f,i)=>row(`<div style="flex:1"><b>${esc(f.name)}</b><small>${(f.size/1024).toFixed(0)} KB</small><div class="sx-pb"><i id="p${i}"></i></div></div>`,i)).join('');$('#uO').disabled=!F.length};
const take=l=>{[...l].forEach(f=>{if(!/\.(pdf|jpe?g|png)$/i.test(f.name))return toast(f.name+': format tidak didukung');if(f.size>5242880)return toast(f.name+': melebihi 5 MB');F.push(f)});draw()};
dz.onclick=()=>inp.click();inp.onchange=()=>take(inp.files);['dragover','dragenter'].forEach(v=>dz.addEventListener(v,e=>{e.preventDefault();dz.classList.add('ov')}));['dragleave','drop'].forEach(v=>dz.addEventListener(v,e=>{e.preventDefault();dz.classList.remove('ov')}));dz.addEventListener('drop',e=>take(e.dataTransfer.files));
$('#uC').onclick=close;$('#uO').onclick=function(){if(!$('#uS').value.trim())return toast('Isi nama siswa terlebih dahulu');this.disabled=true;let n=0;F.forEach((f,i)=>{let p=0;const t=setInterval(()=>{p+=12+Math.random()*20;if(p>=100){p=100;clearInterval(t);if(++n==F.length)fin()}$('#p'+i).style.width=p+'%'},180)});
 const fin=()=>{F.forEach(f=>DOK.push({nama:f.name,jenis:$('#uJ').value,siswa:$('#uS').value.trim(),w:Date.now()}));SV('siadds_dok',DOK);bump(3,F.length);logAdd(`Admin mengunggah ${F.length} berkas ${esc($('#uJ').value)} untuk ${esc($('#uS').value.trim())}.`);setTimeout(()=>{close();toast(F.length+' berkas berhasil diunggah')},400)}}}
/* ===== Kartu KPI ===== */
const KD=[['Total Seluruh Siswa','Gabungan siswa aktif dan calon yang sudah dikonversi.',[['Kelas X','98'],['Kelas XI','94'],['Kelas XII','94']],'siswa'],['Siswa Aktif','Siswa terdaftar pada rombel aktif TA berjalan.',[['Laki-laki','132'],['Perempuan','154']],'siswa'],['Calon Baru PPDB','Pendaftar gelombang 1 dan 2 yang masih berproses.',[],'calon'],['Total Dokumen','Seluruh PDF dan scan digital di arsip.',[['KK','332'],['Akta','321'],['Pas Foto','311'],['Ijazah/SKL','301']],'upload'],['Dokumen Lengkap','Berkas wajib yang sudah terverifikasi.',[],'upload'],['Belum Lengkap','Berkas yang memerlukan tindak lanjut.',[],'tabel'],['Perlu Perbaikan','Berkas buram atau format tidak sesuai.',[],'tabel']];
$$('.kpi').forEach((c,i)=>c.addEventListener('click',()=>{const d=KD[i];if(!d)return;const act={siswa:'<button class="sx-b g" data-a="add">+ Tambah Siswa</button>',calon:`<a class="sx-b g" href="${R.calon}" style="text-decoration:none">Buka Data Calon</a>`,upload:'<button class="sx-b g" data-a="up">Upload Dokumen</button>',tabel:'<button class="sx-b g" data-a="tb">Lihat Berkas Bermasalah</button>'}[d[3]];
 open(d[0],`<p class="mu" style="line-height:1.6">${d[1]}</p><div style="font-size:44px;font-weight:800;margin:10px 0">${K[i].textContent}</div>${d[2].map((r,j)=>row(`<span>${r[0]}</span><b>${r[1]}</b>`,j)).join('')}<div class="sx-a">${act}</div>`,1);
 $('[data-a=add]',box)&&($('[data-a=add]',box).onclick=formSiswa);$('[data-a=up]',box)&&($('[data-a=up]',box).onclick=formUpload);$('[data-a=tb]',box)&&($('[data-a=tb]',box).onclick=()=>{close();$('table').scrollIntoView({behavior:'smooth',block:'center'})})}));
/* ===== Daftar & panel sidebar ===== */
const listSis=(t,arr,sub)=>{open(t,`<input class="sx-s" id="sq" placeholder="Cari nama atau NISN..." style="margin:0 0 12px"><div id="sl"></div>`,1);const dr=q=>{$('#sl').innerHTML=arr().filter(a=>(a[0]+a[2]).toLowerCase().includes(q.toLowerCase())).map((a,i)=>row(`<div><b>${esc(a[0])}</b><small>${esc(a[1])} • NISN ${a[2]}</small></div><span class="pill">${a[3]=='L'?'Laki-laki':'Perempuan'}</span>`,i,'data-p="'+a[2]+'"')).join('')||'<p class="mu">Tidak ditemukan.</p>'};dr('');$('#sq').oninput=e=>dr(e.target.value);$('#sl').onclick=e=>{const r=e.target.closest('[data-p]');if(r){const a=arr().find(x=>x[2]==r.dataset.p);profil(a)}}};
const sisAll=()=>[...AKT,...SIS.map(s=>[s.nama,s.kelas,s.nisn,s.jk])];
const profil=a=>open('Detail Profil Siswa',`<div style="display:flex;gap:14px;align-items:center;margin-bottom:14px"><div class="av" style="width:56px;height:56px;font-size:20px">${esc(a[0][0])}</div><div><b style="font-size:17px">${esc(a[0])}</b><br><span class="mu">${esc(a[1])}</span></div></div>${[['NISN',a[2]],['Jenis Kelamin',a[3]=='L'?'Laki-laki':'Perempuan'],['Status','Aktif'],['Kelengkapan Berkas','KK, Akta, Foto, Ijazah']].map((r,i)=>row(`<span>${r[0]}</span><b>${r[1]}</b>`,i)).join('')}<div class="sx-a"><button class="sx-b" id="bk">← Kembali</button></div>`,1)||($('#bk').onclick=()=>listSis('Data Siswa Aktif',sisAll));
const konv=()=>{const L=()=>CLN.filter(c=>!KON.includes(c[2]));open('Daftar Ulang & Konversi',`<p class="mu" style="margin-bottom:12px">Calon yang lolos dan daftar ulang dapat dikonversi menjadi siswa aktif.</p><div id="kl"></div>`,1);const dr=()=>{$('#kl').innerHTML=L().map((c,i)=>row(`<div><b>${c[0]}</b><small>${c[1]}</small></div><button class="sx-b g" data-k="${c[2]}">Konversi</button>`,i)).join('')||'<p class="mu">Semua calon sudah dikonversi.</p>'};dr();$('#kl').onclick=e=>{const k=e.target.dataset.k;if(!k)return;KON.push(k);SV('siadds_konversi',KON);bump(1,1);bump(2,-1);logAdd('Admin mengonversi calon siswa menjadi siswa aktif.');toast('Konversi berhasil');dr()}};
const bars=[['Kartu Keluarga (KK)',97],['Akta Kelahiran',94],['Pas Foto 3x4 Resmi',91],['Ijazah / SKL',88]];
const panel={'Kelengkapan Dokumen':()=>open('Kelengkapan Dokumen',bars.map((b,i)=>row(`<div style="flex:1"><b>${b[0]}</b> <span style="float:right">${b[1]}%</span><div class="sx-pb"><i style="width:0" data-w="${b[1]}"></i></div></div>`,i)).join(''),1)||setTimeout(()=>$$('[data-w]',box).forEach(e=>e.style.width=e.dataset.w+'%'),200),
'Direktori Arsip Digital':()=>open('Direktori Arsip Digital',[['Kartu Keluarga',332],['Akta Kelahiran',321],['Pas Foto',311],['Ijazah / SKL',301],['Unggahan Baru',DOK.length]].map((f,i)=>row(`<span>📁 ${f[0]}</span><b>${f[1]} berkas</b>`,i)).join('')+DOK.slice(-5).reverse().map((d,i)=>row(`<div><b>${esc(d.nama)}</b><small>${esc(d.jenis)} • ${esc(d.siswa)}</small></div>`,i+5)).join(''),1),
'Lokasi Arsip Fisik':()=>open('Lokasi Arsip Fisik',[['Lemari A • Rak 02','Map 041–045 (PPDB)'],['Lemari A • Rak 01','Map 001–040'],['Lemari B • Rak 01','Arsip Alumni']].map((r,i)=>row(`<div><b>${r[0]}</b><small>${r[1]}</small></div>`,i)).join(''),1),
'Data Siswa Aktif':()=>listSis('Data Siswa Aktif',sisAll),'Detail Profil Siswa':()=>listSis('Pilih Siswa',sisAll),'Data Alumni':()=>listSis('Data Alumni',()=>ALM),'Daftar Ulang & Konversi':konv,'Tambah Siswa Baru':formSiswa,'Upload Dokumen':formUpload,'Cetak Label QR Code':cetak};
function cetak(){const w=window.open('','_blank','width=720,height=600');if(!w)return toast('Izinkan pop-up untuk mencetak label');w.document.write(`<title>Label Map</title><style>body{font-family:Arial;display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:16px}.l{border:2px solid #000;border-radius:8px;padding:12px;text-align:center}.b{height:46px;margin:8px 0;background:repeating-linear-gradient(90deg,#000 0 2px,#fff 2px 4px,#000 4px 5px,#fff 5px 8px)}</style>`+[41,42,43,44,45].map(n=>`<div class="l"><b>MAS YPI SUMBER HARJO</b><div class="b"></div>Map ${String(n).padStart(3,'0')} • RAK-BMT-02<br>Lemari A • Rak 02</div>`).join('')+'<script>onload=()=>print()<\/script>');w.document.close();toast('Label siap dicetak')}
/* ===== Pasang ke tombol ===== */
$$('.side a[href="#"]').forEach(a=>{const f=panel[a.textContent.trim()];a.addEventListener('click',e=>{e.preventDefault();f?f():toast('Menu belum tersedia')})});
$$('a[href="#"]').forEach(a=>{const t=a.textContent.trim();if(a.closest('.side'))return;a.addEventListener('click',e=>{e.preventDefault()});
 if(t=='Tambah Siswa')a.addEventListener('click',formSiswa);if(t=='Upload Dokumen')a.addEventListener('click',formUpload);if(t.startsWith('Cetak Barcode'))a.addEventListener('click',cetak);
 if(t.startsWith('Lihat Seluruh Log'))a.addEventListener('click',()=>open('Log Keamanan',$$('.log').map((l,i)=>row(`<div>${l.childNodes[0].textContent}<small>${l.querySelector('small')?.textContent||''}</small></div>`,i)).join(''),1))});
/* Quick Action */
const qa=$$('.top a.btn.g')[0],wrap=qa.parentNode;wrap.style.position='relative';const mn=document.createElement('div');mn.className='sx-mn';
mn.innerHTML=`<button data-q="s">＋ Tambah Siswa Baru</button><button data-q="u">⬆ Upload Dokumen</button><a href="${R.pendaftaran}">👤 Pendaftaran Baru</a><a href="${R.verifikasi}">✔ Verifikasi Berkas</a><a href="${R.seleksi}">📈 Status & Seleksi</a><button data-q="c">🖨 Cetak Label QR</button>`;qa.after(mn);
qa.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();mn.classList.toggle('on')});mn.addEventListener('click',e=>{const q=e.target.dataset.q;if(q){mn.classList.remove('on');({s:formSiswa,u:formUpload,c:cetak})[q]()}});document.addEventListener('click',e=>{if(!mn.contains(e.target))mn.classList.remove('on')});
/* Pencarian */
const si=$('.top input[type=search]'),sl=si.closest('label');sl.style.position='relative';const sr=document.createElement('div');sr.className='sx-sr';sl.appendChild(sr);
si.addEventListener('input',()=>{const q=si.value.trim().toLowerCase();if(!q){sr.style.display='none';return}
 const m=$$('.side a').map(a=>({t:a.textContent.trim(),k:'Menu',f:()=>a.click()})).concat(sisAll().map(a=>({t:a[0],k:'Siswa • '+a[1],f:()=>profil(a)})),$$('tbody tr').map(r=>({t:r.cells[0].querySelector('b').textContent,k:'Dokumen • '+r.cells[2].textContent,f:()=>r.click()}))).filter(x=>x.t.toLowerCase().includes(q)).slice(0,8);
 sr.innerHTML=m.map((x,i)=>`<button data-i="${i}">${esc(x.t)} <small>${esc(x.k)}</small></button>`).join('')||'<button disabled>Tidak ada hasil</button>';sr.style.display='block';sr._m=m});
sr.addEventListener('click',e=>{const b=e.target.closest('[data-i]');if(b){sr._m[b.dataset.i].f();sr.style.display='none';si.value=''}});document.addEventListener('click',e=>{if(!sl.contains(e.target))sr.style.display='none'});
/* Baris tabel berkas */
$$('tbody tr').forEach(r=>{r.style.cursor='pointer';r.addEventListener('click',()=>{const c=[...r.cells].map(x=>x.textContent.trim()),chip=r.querySelector('.chip'),need=chip&&chip.textContent.includes('Perbaikan');
 open('Detail Berkas',[['Siswa',r.cells[0].querySelector('b').textContent],['Kelas / Reg',c[1]],['Dokumen',c[2]],['Catatan',c[3]],['Tgl Unggah',c[4]],['Status',chip?chip.textContent:'-']].map((x,i)=>row(`<span>${x[0]}</span><b style="text-align:right">${esc(x[1])}</b>`,i)).join('')+`<div class="sx-a"><button class="sx-b" id="dc">Tutup</button><button class="sx-b g" id="dok" ${chip&&chip.textContent=='Terverifikasi'?'disabled':''}>Tandai Terverifikasi</button></div>`);
 $('#dc').onclick=close;$('#dok').onclick=()=>{chip.textContent='Terverifikasi';chip.className='chip';chip.style.cssText='background:#dcfce7;color:#166534';if(need){bump(6,-1);bump(4,1)}else{bump(5,-1);bump(4,1)}logAdd('Admin memverifikasi berkas '+esc(c[2])+' milik '+esc(r.cells[0].querySelector('b').textContent)+'.');close();toast('Berkas ditandai terverifikasi')}})});
})();
</script>